item.description:
instead of making suffix min array in problem E, we can simply track the max gain by maintaining two state variables... My Code#include<iostream>
#include<vector>

using namespace std;

int main() {
    int t;
    cin &gt;&gt; t;

    while (t--) {
        int n;
        cin &gt;&gt; n;

        vector<int> v(n);
        for (int i = 0; i &lt; n; i++) cin &gt;&gt; v[i];

        long long base = 0;
        int cur_min = INT_MAX;
        long long gain = 0, cur_gain = 0;

        for (int i = n-1; i &gt;= 0; i--) {
            if (v[i] &lt; cur_min) {
                cur_min = v[i];
                cur_gain = 0;
            }
            else {
                base += v[i] - cur_min;
                gain = max(gain, ++cur_gain);
            }
        }

        cout &lt;&lt; base + gain &lt;&lt; "\n";
    }

    return 0;
}
</int></vector></iostream>
